 projektet","href":"/projekt-kontor"},"gallery":{"order":["i1","i2","i3","i4","i5","i6","i7","i8"],"items":{"i1":{"image":{"src":"/photos/kontor-1.webp","variants":[{"width":480,"src":"/photos/kontor-1-480.webp"},{"width":800,"src":"/photos/kontor-1-800.webp"},{"width":1013,"src":"/photos/kontor-1.webp"}],"alt":"Kontorslokal under ombyggnad med nya väggar"},"caption":""},"i2":{"image":{"src":"/photos/kontor-2.webp","variants":[{"width":480,"src":"/photos/kontor-2-480.webp"},{"width":800,"src":"/photos/kontor-2-800.webp"},{"width":1013,"src":"/photos/kontor-2.webp"}],"alt":"Kontorslokal under ombyggnad med nya väggar"},"caption":""},"i3":{"image":{"src":"/photos/kontor-3.webp","variants":[{"width":480,"src":"/photos/kontor-3-480.webp"},{"width":800,"src":"/photos/kontor-3-800.webp"},{"width":1013,"src":"/photos/kontor-3.webp"}],"alt":"Kontorslokal under ombyggnad med nya väggar"},"caption":""},"i4":{"image":{"src":"/photos/kontor-4.webp","variants":[{"width":480,"src":"/photos/kontor-4-480.webp"},{"width":800,"src":"/photos/kontor-4-800.webp"},{"width":1013,"src":"/photos/kontor-4.webp"}],"alt":"Kontorslokal under ombyggnad med nya väggar"},"caption":""},"i5":{"image":{"src":"/photos/kontor-5.webp","variants":[{"width":480,"src":"/photos/kontor-5-480.webp"},{"width":800,"src":"/photos/kontor-5-800.webp"},{"width":1013,"src":"/photos/kontor-5.webp"}],"alt":"Kontorslokal under ombyggnad med nya väggar"},"caption":""},"i6":{"image":{"src":"/photos/kontor-6.webp","variants":[{"width":480,"src":"/photos/kontor-6-480.webp"},{"width":800,"src":"/photos/kontor-6-800.webp"},{"width":1013,"src":"/photos/kontor-6.webp"}],"alt":"Kontorslokal under ombyggnad med nya väggar"},"caption":""},"i7":{"image":{"src":"/photos/kontor-glas.webp","variants":[{"width":480,"src":"/photos/kontor-glas-480.webp"},{"width":800,"src":"/photos/kontor-glas-800.webp"},{"width":1013,"src":"/photos/kontor-glas.webp"}],"alt":"Glasvägg mot mötesrum i en ombyggd kontorslokal"},"caption":""},"i8":{"image":