om litet.","button":{"label":"","href":"/"},"image":{"src":"/photos/kontor-glas.webp","variants":[{"width":480,"src":"/photos/kontor-glas-480.webp"},{"width":800,"src":"/photos/kontor-glas-800.webp"},{"width":1013,"src":"/photos/kontor-glas.webp"}],"alt":"Glasvägg mot mötesrum i en ombyggd kontorslokal","focus":"50% 45%"},"size":"medium"},"s2":{"type":"about","hidden":false,"anchor":"","label":"","eyebrow":"Om Västkust Bygg","heading":"Ett byggföretag med kompetens","subheading":"Västkust Bygg & Montage AB är med er hela vägen, från idé till färdigt projekt. Vi erbjuder en helhetslösning där kompetens, noggrannhet och tydlighet är viktiga faktorer för oss. Vår erfarenhet och expertis inom byggbranschen gör oss till det optimala valet för ditt projekt.","text":"Vår unika helhetslösning skiljer oss från konkurrenterna. Genom att integrera kompetens, noggrannhet och tydlighet levererar vi enastående resultat som överträffar förväntningarna. Vårt dedikerade team står redo att ta ansvar och säkerställa att varje projekt blir en framgång.\n\nVästkust Bygg & Montage AB:s hantverkare har lång erfarenhet inom byggbranschen, vilket gör oss till en pålitlig partner för ditt projekt. Vi strävar alltid efter att leverera högkvalitativt arbete och nöjda kunder.","facts":{"order":["i1","i2","i3","i4","i5","i6"],"items":{"i1":{"label":"Arbetsledare","value":"Emanuel Ström"},"i2":{"label":"Område","value":"Göteborg med omnejd"},"i3":{"label":"Våtrum","value":"Behörig enligt BBV"},"i4":{"label":"Försäkring","value":"Länsförsäkringar"},"i5":{"label":"Arbetsplats","value":"ID06 och personalliggare"},"i6":{"label":"Öppettider","value":"Måndag–fredag 08.00–17.00"}}},"link":{"label":"","href":"/"},"image":{"src":"/photos/bad1-6.webp","variants":[{"width":480,"src":"/photos/bad1-6-480.webp"},{"width":800,"src":"/photos/bad1-6-800.webp"},{"width":1013,"src":"/photos/bad1-6.webp"}],"alt":"Badrum renoverat av Västkust Bygg","focus":"50% 50%"},"badgeValue":"5/5","badgeLabel":"i omdömen"},"s3":{"type":"values","hidden":false,"anchor":"","label":"","eyebrow":"Varför arbeta med oss","heading":"Vår unika företagsidentitet","text":"Västkust Bygg & Montage AB:s hantverkare har lång erfarenhet inom byggbranschen, vilket gör oss till en pålitlig partner för ditt projekt. Vi strävar alltid efter att leverera högkvalitativt arbete och nöjda kunder.","items":{"order":["i1","i2","i3"],"items":{"i1":{"heading":"Skickliga hantverkare","text":"Vi har ett team av skickliga hantverkare som är experter inom sitt arbete och levererar högkvalitativa resultat med precision och noggrannhet.","icon":"HardHat"},"i2":{"heading":"Innovativa lösningar","text":"Vi strävar efter att implementera innovativa lösningar och tekniker i våra projekt för att säkerställa effektivitet, hållbarhet och modern design.","icon":"Wrench"},"i3":{"heading":"Kundanpassad service","text":"Vår kundanpassade service innebär att vi lyssnar aktivt på våra kunders önskemål och behov för att skapa skräddarsydda lösningar som överträffar deras förväntningar.","icon":"Users"}}}},"s4":{"type":"process","hidden":false,"anchor":"sa-gar-det-till","label":"","eyebrow":"Så går det till","heading":"Från idé till färdigt projekt","text":"","steps":{"order":["i1","i2","i3","i4"],"items":{"i1":{"title":"Idé och kontakt","description":"Du ringer, mejlar eller fyller i formuläret och berättar vad du vill göra.","icon":"Phone"},"i2":{"title":"Besök och offert","description":"Vi tittar på plats och lämnar en skräddarsydd offert med vad som ingår.","icon":"MapPin"},"i3":{"title":"Vi bygger","description":"En kontaktperson, tydlig tidplan och ordning och reda på arbetsplatsen.","icon":"FileText"},"i4":{"title":"Klart och dokumenterat","description":"Gemensam genomgång – och för våtrum ett kvalitetsdokument enligt BBV.","icon":"Wrench"}}}},"s5":{"type":"testimonials","hidden":false,"anchor":"omdomen","label":"","eyebrow":"Omdömen","heading":"Vad kunderna säger","text":"i alla omdömen","items":{"order":["r2","r1","r5","r3","r4"],"items":{"r2":{"title":"Badrumsrenovering","quote":"Västkust Bygg och Montage har nu renoverat vårt badrum. Emanuel Ström har genomfört renoveringen väldigt professionellt och har under hela processen givit goda råd och lyssnat på oss som kunder. Vi anlitar gärna detta företag fler gånger.","name":"Ingvar Nore","detail":"Google","rating":5,"image":null},"r1":{"title":"Helrenovering av badrum","quote":"Vi är supernöjda med Västkust Bygg och Emanuel som totalrenoverat vårt badrum. Ordning och reda, snyggt och prydligt från start till mål. Vi fick hjälp med att bolla idéer och lösningsförslag under projektets gång. Vi kommer absolut anlita dem igen och rekommendera Västkust Bygg till våra vänner och bekanta.","name":"Lotta","detail":"Malevik, 26 maj 2025","rating":5,"image":null},"r5":{"title":"Foga om vid ett handfat och dusch","quote":"Jag rekommenderar detta företag för att de är snabba, har ett proffsigt bemötande och sätter kunden i fokus. De får 5 stjärnor av 5 möjliga.","name":"Niclas","detail":"Hovås, 2 nov 2024","rating":5,"image":null},"r3":{"title":"Helrenovering av badrum","quote":"Bra genomfört arbete där arbetet utförts enligt utsatt tid. Uppskattar snabb kommunikation under hela processen. Nöjd med resultatet och kommer anlita Västkust Bygg och Montage AB till andra uppdrag framöver. Kan varmt rekommendera dem.","name":"Maria","detail":"Lindome, 15 apr 2025","rating":5,"image":null},"r4":{"title":"Reparera fukt ovanför ett sovrumsfönster","quote":"Jag kommer att anlita dem igen. Jag hade inget stort byggprojekt men kände att jag var lika prioriterad som de med större projekt. Kanonbemötande 😃","name":"Suzanne","detail":"Västra Frölunda, 15 okt 2024","rating":5,"image":null}}}},"s6":{"type":"cta","hidden":false,"anchor":"","label":"","eyebrow":"","heading":"Har du ett projekt på gång?","text":"Berätta vad du vill göra så återkommer vi med en skräddarsydd offert. Måndag–fredag 08.00–17.00.","button":{"label":"Begär offert","href":"#offert"}}}}},"kontakt":{"slug":"kontakt","title":"Kontakt","seo":{"title":"Kontakt och offert","description":"Begär offert från Västkust Bygg & Montage AB. Ring 076-882 03 33 eller mejla info@vastkustbygg.se. Måndag–fredag 08–17."},"sections":{"order":["bild","s2","s3","s4"],"items":{"bild":{"type":"pageHero","hidden":false,"anchor":"","label":"","eyebrow":"Kontakt","heading":"Begär offert","text":"Få en skräddarsydd offert för ditt byggprojekt. Vårt team är redo att hjälpa dig.","button":{"label":"","href":"/"},"image":{"src":"/photos/kok-efter-2.webp","variants":[{"width":480,"src":"/photos/kok-efter-2-480.webp"},{"width":800,"src":"/photos/kok-efter-2-800.webp"},{"width":1200,"src":"/photos/kok-efter-2-1200.webp"},{"width":1800,"src":"/photos/kok-efter-2.webp"}],"alt":"Det nya köket från andra hållet med fönster och spotlightskena","focus":"50% 50%"},"size":"medium"},"s2":{"type":"contact","hidden":false,"anchor":"kontakt","label":"","eyebrow":"Kontakt","heading":"Kontakta oss","text":"Få en skräddarsydd offert för ditt byggprojekt. Hör av dig så återkommer vi – vill du hellre ringa går det lika bra.","phoneLabel":"Telefon","emailLabel":"E-post","addressLabel":"Område","openingHoursLabel":"Öppettider","orgLabel":"Org.nr","formHeading":"Begär offert"},"s3":{"type":"area","hidden":false,"anchor":"","label":"","eyebrow":"Område","heading":"Vi bygger i Göteborg med omnejd","text":"Våra kunder finns bland annat här. Ligger ditt projekt utanför – hör av dig ändå.","places":{"order":["i1","i2","i3","i4","i5","i6","i7"],"items":{"i1":{"label":"Göteborg"},"i2":{"label":"Mölndal"},"i3":{"label":"Partille"},"i4":{"label":"Härryda"},"i5":{"label":"Lerum"},"i6":{"label":"Kungälv"},"i7":{"label":"Ale"}}},"link":{"label":"Öppna i Google Maps","href":"https://www.google.com/maps/place/?q=place_id:ChIJrz2xu5lvzC4RC-5UkH9xpUw"},"mapQuery":"Göteborg"},"s4":{"type":"faq","hidden":false,"anchor":"fragor","label":"","eyebrow":"Vanliga frågor","heading":"Frågor och svar","phonePrompt":"Hittar du inte svaret? Ring","items":{"order":["i1","i2","i3","i4","i5","i6"],"items":{"i1":{"question":"Vilka uppdrag tar ni?","answer":"Badrums- och köksrenoveringar, renoveringar och ombyggnationer, lokalanpassningar och nybyggnation – men även mindre jobb som fuktskador och omfogning."},"i2":{"question":"Är ni behöriga att bygga badrum?","answer":"Ja. Vi har gått Byggkeramikrådets utbildning och arbetar efter branschreglerna BBV. När badrummet är klart får du ett Kvalitetsdokument."},"i3":{"question":"Hur får jag en offert?","answer":"Fyll i formuläret, mejla info@vastkustbygg.se eller ring 076-882 03 33. Oftast vill vi se på plats innan vi lämnar en offert som håller."},"i4":{"question":"Var arbetar ni?","answer":"Främst i Göteborg, Mölndal, Partille, Härryda, Lerum, Kungälv och Ale. Ligger ditt projekt någon annanstans – hör av dig så svarar vi om vi kan ta det."},"i5":{"question":"Gäller ROT-avdrag?","answer":"ROT-avdraget gäller arbetskostnaden för många renoveringar och ombyggnader i bostäder. Vi visar hur det påverkar priset i offerten."},"i6":{"question":"Är ni försäkrade?","answer":"Ja. Bolaget har allrisk- och ansvarsförsäkring via Länsförsäkringar, och de anställda omfattas av kollektivavtalade försäkringar via FORA."}}}}}}},"integritetspolicy":{"slug":"integritetspolicy","title":"Integritetspolicy","seo":{"title":"Integritetspolicy","description":"Så hanterar Västkust Bygg & Montage AB personuppgifterna du lämnar när du skickar en offertförfrågan."},"sections":{"order":["bild","ansvar","uppgifter","varfor","hur-lange","leverantorer","kakor","rattigheter"],"items":{"bild":{"type":"pageHero","hidden":false,"anchor":"","label":"","eyebrow":"Integritet","heading":"Integritetspolicy","text":"Så hanterar vi uppgifterna du lämnar när du kontaktar oss.","button":{"label":"","href":"#"},"image":{"src":"/photos/bad2-under.webp","variants":[{"width":480,"src":"/photos/bad2-under-480.webp"},{"width":800,"src":"/photos/bad2-under-800.webp"},{"width":832,"src":"/photos/bad2-under.webp"}],"alt":"Duschhörna med nya plattor och golvbrunn under arbetet","focus":"50% 60%"},"size":"medium"},"ansvar":{"type":"text","hidden":false,"anchor":"","label":"","eyebrow":"","heading":"Vem ansvarar för dina uppgifter?","paragraphs":["Västkust Bygg & Montage AB (org.nr 559071-1999) ansvarar för de personuppgifter som lämnas via webbplatsen. Har du frågor når du oss på info@vastkustbygg.se eller 076-882 03 33."],"image":null,"imageSide":"right","button":null,"tone":"light"},"uppgifter":{"type":"text","hidden":false,"anchor":"","label":"","eyebrow":"","heading":"Vilka uppgifter vi sparar","paragraphs":["När du skickar en offertförfrågan sparar vi det du fyller i: namn, telefonnummer, e-postadress, typ av projekt och din beskrivning.","För att stoppa skräppost sparar vi också en kod som räknas fram ur din IP-adress. Koden går inte att räkna tillbaka till adressen."],"image":null,"imageSide":"right","button":null,"tone":"light"},"varfor":{"type":"text","hidden":false,"anchor":"","label":"","eyebrow":"","heading":"Varför vi använder dem","paragraphs":["Vi använder uppgifterna för att svara på din förfrågan, ta fram en offert och hålla kontakten om jobbet. Det gör vi för att du har bett om en offert. Blir det ett uppdrag använder vi uppgifterna för att kunna utföra det.","Vi säljer inte dina uppgifter och skickar ingen reklam till dig."],"image":null,"imageSide":"right","button":null,"tone":"light"},"hur-lange":{"type":"text","hidden":false,"anchor":"","label":"","eyebrow":"","heading":"Hur länge vi sparar dem","paragraphs":["Förfrågningar som inte leder till ett uppdrag raderar vi senast 12 månader efter att vi har svarat. Blir det ett uppdrag sparar vi det som behövs för faktura och garanti så länge lagen kräver, till exempel sju år enligt bokföringslagen."],"image":null,"imageSide":"right","button":null,"tone":"light"},"leverantorer":{"type":"text","hidden":false,"anchor":"","label":"","eyebrow":"","heading":"Vilka som hanterar uppgifterna åt oss","paragraphs":["Förfrågningarna lagras hos Supabase på servrar i Stockholm. Webbplatsen visas via GitHub Pages, som tar emot din IP-adress när du besöker sidan, precis som alla webbservrar. GitHub finns i USA och omfattas av EU:s och USA:s ramverk för dataskydd.","Leverantörerna får bara använda uppgifterna för att leverera sin tjänst till oss."],"image":null,"imageSide":"right","button":null,"tone":"light"},"kakor":{"type":"text","hidden":false,"anchor":"","label":"","eyebrow":"","heading":"Kakor och karta","paragraphs":["Webbplatsen använder inga kakor för statistik eller marknadsföring. På kontaktsidan finns en karta från Google Maps. När kartan visas tar Google emot din IP-adress och kan sätta egna kakor enligt Googles integritetspolicy."],"image":null,"imageSide":"right","button":null,"tone":"light"},"rattigheter":{"type":"text","hidden":false,"anchor":"","label":"","eyebrow":"","heading":"Dina rättigheter","paragraphs":["Du har rätt att få veta vilka uppgifter vi har om dig, att få fel rättade och att få uppgifterna raderade. Mejla info@vastkustbygg.se så hjälper vi dig.","Tycker du att vi hanterar dina uppgifter fel kan du vända dig till Integritetsskyddsmyndigheten (IMY) på imy.se."],"image":null,"imageSide":"right","button":null,"tone":"light"}}}}}}}$baseline$::jsonb)
on conflict (id) do nothing;

insert into public.content_revisions (version, snapshot, source, summary)
select 1, data, 'baseline', 'Ursprunglig version' from public.site_snapshot
where id = 1 and not exists (select 1 from public.content_revisions where source = 'baseline');

select private.set_theme_tables(data -> 'theme') from public.site_snapshot where id = 1;

insert into public.website_colors (scope, key, value) values ('admin', 'primary', '#1572D3')
on conflict (scope, key) do nothing;

insert into private.admin_allowlist (email) values ('info@vastkustbygg.se') on conflict do nothing;

insert into public.credit_balance (account_id, balance) values ('site', 100) on conflict (account_id) do nothing;
insert into public.credit_transactions (amount, type, description, balance_after)
select 100, 'grant', 'Startkredit som ingår i abonnemanget', 100
where not exists (select 1 from public.credit_transactions);

-- The packs offered under "Fyll på credits". Prices are set by Elevate Studio (null: shown as per agreement).
insert into public.settings (key, value) values
  ('credit_packs', '[{"credits": 50, "price": null}, {"credits": 100, "price": null}, {"credits": 250, "price": null}, {"credits": 500, "price": null}]'),
  ('onboarding', '{"done": [], "dismissed": false}'),
  ('deploy', '{"status": "idle"}')
on conflict (key) do nothing;
